def greet(name, greeting="Hello"):
    return greeting + ", " + name

print(greet(greeting="Hi", "Ada"))

def total(*numbers):
    print(numbers, type(numbers))
    return sum(numbers)

print(total(1, 2, 3))
print(total())

def connect(host, *, timeout=10):
    return host, timeout

print(connect("db", 30))

def show(**options):
    for key, value in options.items():
        print(key, "=", value)

show(color="red", size=3)

def area(width, height):
    return width * height

size = (3, 4)
print(area(*size))

dims = {"width": 5, "height": 2}
print(area(**dims))

a = [1, 2]
b = [3]
print([*a, *b, 4])

defaults = {"debug": False, "port": 80}
custom = {"port": 8080}
print({**defaults, **custom})

